#define TEST_SECTOR_SIZE              512u
#define TEST_PARTITION_OFFSET         446u
#define TEST_PARTITION_TYPE_OFFSET    4u
#define TEST_PARTITION_START_OFFSET   8u
#define TEST_PARTITION_SIZE_OFFSET    12u

extern UINT _fx_partition_offset_calculate_extended(FX_MEDIA *media_ptr, void *partition_sector,
                                                     UINT partition, ULONG *partition_start,
                                                     ULONG *partition_size);
void test_control_return(UINT status);
void test_application_define(void *first_unused_memory);

typedef enum TEST_DRIVER_MODE_ENUM
{
    TEST_DRIVER_SUCCESS,
    TEST_DRIVER_READ_ERROR,
    TEST_DRIVER_BAD_SIGNATURE,
    TEST_DRIVER_EMPTY_PARTITION,
    TEST_DRIVER_CHAIN
} TEST_DRIVER_MODE;

static TEST_DRIVER_MODE test_driver_mode;

/* Supply an extended boot record or a controlled read error.  */
static void test_partition_driver(FX_MEDIA *media_ptr)
{
UCHAR *sector;

    if (test_driver_mode == TEST_DRIVER_READ_ERROR)
    {
        media_ptr->fx_media_driver_status = FX_IO_ERROR;
        return;
    }

    sector = (UCHAR *)media_ptr->fx_media_driver_buffer;
    (void)memset(sector, 0, TEST_SECTOR_SIZE);
    sector[510] = (UCHAR)0x55;
    sector[511] = (UCHAR)0xAA;
    if (test_driver_mode == TEST_DRIVER_BAD_SIGNATURE)
    {
        sector[510] = (UCHAR)0;
    }
    if (test_driver_mode != TEST_DRIVER_EMPTY_PARTITION)
    {
        sector[TEST_PARTITION_OFFSET + TEST_PARTITION_TYPE_OFFSET] = (UCHAR)0x0B;
        sector[TEST_PARTITION_OFFSET + TEST_PARTITION_START_OFFSET] = (UCHAR)3;
        sector[TEST_PARTITION_OFFSET + TEST_PARTITION_SIZE_OFFSET] = (UCHAR)9;
    }
    if (test_driver_mode == TEST_DRIVER_CHAIN)
    {
        if (media_ptr->fx_media_driver_logical_sector == (ULONG)7)
        {
            sector[TEST_PARTITION_OFFSET + 16u + TEST_PARTITION_TYPE_OFFSET] = (UCHAR)0x05;
            sector[TEST_PARTITION_OFFSET + 16u + TEST_PARTITION_START_OFFSET] = (UCHAR)20;
        }
        else
        {
            sector[TEST_PARTITION_OFFSET + TEST_PARTITION_START_OFFSET] = (UCHAR)4;
        }
    }
    media_ptr->fx_media_driver_status = FX_SUCCESS;
}

/* Verify boot records, primary partitions, and extended partition reads.  */
